-- Figures live in public/q/nov23/. Ids are fixed, so running this file again updates the test instead of copying it.

-- PeaklyTest Nov 2023 · Reading & Writing · Module 1
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('8a949f69-7eab-5adc-93df-152fc756fe1d', 'PeaklyTest Nov 2023 · Reading & Writing · Module 1', 'Reading & Writing', 'Reading & Writing, Module 1 of the Nov 2023 PeaklyTest · 27 questions · 32 minutes', 32, 320, true, 'PeaklyTest Nov 2023 · Reading & Writing', 1)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('347e609e-1f80-5275-99c9-2860a89c9f55', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice completes the text with the most logical and precise word or phrase?', '["rated", "invented", "prevented", "replaced"]'::jsonb, 1, 'Portable video game consoles and wireless speakers tend to contain batteries that can’t be easily _____. Environmental policy researcher Jessika Richter warns that because new batteries can’t be put in once the old ones no longer work, the gadgets stop functioning and are usually disposed of as trash.'),
  ('9f2a14a1-9555-5c50-bdf0-6ddface2f53a', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice completes the text with the most logical and precise word or phrase?', '["complimented by", "uncertain about", "unbothered by", "inspired by"]'::jsonb, 2, 'Whether Carmen Lomas Garza is creating small paintings and illustrations or large public artworks—such as Baile, a copper cutout of traditional Mexican dance in the San Francisco International Airport—she is _____ direct experience, drawing from memories of her childhood in Texas or details of her current surroundings in California.'),
  ('257164e1-682f-5422-b0b9-4b2b815132a7', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice completes the text with the most logical and precise word or phrase?', '["confirm", "acquire", "develop", "attract"]'::jsonb, 3, 'Domesticated thousands of years ago by Indigenous people in South America, the potato deviates structurally from the wild plant it is descended from. Summer squash, another crop domesticated by Indigenous Americans, shows so little resemblance to any wild plant that genetic research was necessary to _____ the wild Johnny gourd as its ancestor.'),
  ('32fd1f58-7056-5a12-bc15-83aa00940f6e', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice completes the text with the most logical and precise word or phrase?', '["determined", "hesitant", "fortunate", "surprised"]'::jsonb, 4, 'When considering which plays and musicals to produce, theaters in San Francisco often favor keeping audiences happy over taking risks. So while they might be eager to produce an established classic like Amadeus, for example, most would be _____ to stage a work from a relatively unknown playwright.'),
  ('871da9b4-e9bf-51f7-ba7d-d0607e12d8af', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice best states the main purpose of the text?', '["To provide details about Argerich identifies which pieces of music she will perform.", "To assert that Argerich’s performances look effortless because of how she prepares for them.", "To discuss the kinds of music Argerich feels most comfortable encountering for the first time.", "To describe the unique way that Argerich approaches music she hasn’t performed before."]'::jsonb, 5, 'When classical pianist Martha Argerich performs, it appears as if the music is coming to her spontaneously. She’s highly skilled technically, but because of how freely she plays and her willingness to take risks, she seems relaxed and natural. Her apparent ease, however, is due to a tremendous amount of preparation. Despite Argerich’s experience and virtuosity, she never takes for granted that she knows a piece of music. Instead, she approaches the music as if encountering it for the first time and tries to understand it anew.'),
  ('07ebba00-2466-5ff1-8380-69e9d6c23a95', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice best describes the function of the underlined phrase in the text as a whole?', '["It lists species from a family of plants found only on the Hawaiian Islands.", "It provides the common name for the Dubautia waialealae plant.", "It explains why Dubautia waialealae is unique among members of the silversword alliance.", "It supplies the name used to refer to a group of related plant species."]'::jsonb, 6, 'Dubautia waialealae is a species in a family of plants <u>known collectively as the silversword alliance</u>, all of which grow only on the Hawaiian Islands. Members of this alliance exhibit an extraordinary range of phenotypes, with some species maturing into vines and others into shrubs and trees. All species in the alliance descended from a single ancestral tarweed plant that arrived on the islands around 5 million years ago. The tarweed’s descendants diversified into distinct species as they adapted to live in the wide variety of habitats found on the Hawaiian Islands.'),
  ('c8cc4430-bead-5e03-9ae7-7820d662a10f', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice best states the main purpose of the text?', '["To indicate that people sometimes experience feelings of isolation in crowded areas.", "To address common traits that motivate many people to choose to live in urban environments.", "To caution people not to be so quick to dismiss the natural beauty that can be found in rural areas.", "To demonstrate that most people tend to prefer being alone in the country to being alone in towns or cities."]'::jsonb, 7, 'The following text is adapted from Jerome K. Jerome’s 1889 novel Three Men in a Boat (To Say Nothing of the Dog).

We [people] are creatures of the sun. We love light and life. That is why we crowd into the towns and cities, and the country grows more and more deserted every year. In the sunlight—in the daytime, when Nature is alive and busy all around us, we like the open hill-sides and the deepwoods well enough: but in the night, when our Mother Earth has gone to sleep, and left us waking, oh! the world seems so lonesome, and we get frightened, like children in a silent house. Then we sit and sob, and long for the gas-lit streets, and the sound of human voices, and the answering throb of human life.'),
  ('92511574-57a6-5516-bcb6-e42a6aba3e36', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Based on the texts, both authors would most likely agree with which statement?', '["A collaborative approach is necessary to keep temperatures in the Great Lakes region from increasing to the highest predicted levels.", "Agencies involved in natural-resource management in the Great Lakes region should focus their conservation efforts more on the northern pike than on the white-tailed deer.", "Conservation efforts focused on the northern pike are more likely to be successful if they incorporate state and federal agency resources with the knowledge of tribal groups in those efforts.", "State, federal, and tribal groups involved in natural-resource management in the Great Lakes region should immediately begin conservation programs for both the northern pike and white-tailed deer."]'::jsonb, 8, '**Text 1**

According to a study by a conservation group representing 11 tribal nations in the Great Lakes region, the northern pike (ginoozhe in the Ojibwe language) will have significantly worse outcomes over the next 50 years if temperatures increase as much as some models suggest. By contrast, the white-tailed deer (Waawaashkeshi in Ojibwe) should be able to withstand the highest predicted warming without much harm and so likely won’t require the conservation efforts that the northern pike will.

**Text 2**

US government agencies involved in conservation are unfortunately not able to address every possible threat to natural resources. They must use the best information available to decide which species are most threatened and therefore most in need of conservation efforts.'),
  ('397d3897-7a75-5eb3-ae5b-c1dc437f82ca', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'According to the text, what do some historians suggest about Maya civilization?', '["Maya civilization acquired the use of zero from the Olmec civilization.", "Maya civilization respected its historians more than it respected its mathematicians.", "Maya civilization was highly secretive about its intellectual achievements.", "Maya civilization tried to introduce its writing system to other civilizations."]'::jsonb, 9, 'The ancient writing system used in the Maya kingdoms of southern Mexico and Central America had a symbol for the number zero. The earliest known example of the symbol dates to more than 2,000 years ago. At that time, almost none of the writing systems elsewhere in the world possessed a zero symbol. And the use of zero in Mexico and Central America may be even more ancient. Some historians suggest that Maya mathematicians inherited it from the Olmec civilization, which flourished in the region 2,400–3,600 years ago.'),
  ('93537605-7f5a-5a00-b664-6c4b56ff5435', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Based on the text, which choice best explains why the author characterizes the energy ladder as “reductive”?', '["The energy ladder asserts that households only consider one aspect of fuel when making fuel choices, but Heltberg’s study showed that households ignore that characteristic of fuel and evaluate several other factors instead.", "The energy ladder holds that the adoption of one type of fuel means that another type of fuel must be displaced, but Heltberg’s study showed that several different fuel types are typically used in equal proportion.", "The energy ladder assumes that the same factor influences household fuel choice in all locations, but Heltberg’s study showed that fuel choice in Guatemala is influenced by different factors than is fuel choice in Costa Rica.", "The energy ladder attributes household fuel choice primarily to a single characteristic of households, but Heltberg’s study showed that multiple circumstances can affect household fuel choice."]'::jsonb, 10, 'In Costa Rica, use of solid fuel (e.g., coal, wood) as a share of total household fuel use fell by approximately 60 percent between 2000 and 2019; such shifts are typically explained by appeal to the energy ladder, a model holding that fuel choice is mediated mainly by household income (specifically, high-technology fuels displace solid fuels as incomes rise). Rasmus Heltberg’s study of fuel use in Guatemala shows how <u>reductive</u> this model is, however, household fuel use was heterogeneous, flexible, and influenced by several factors, including the local prices of different fuel sources.'),
  ('787d196f-b1a1-5a8c-a61f-469a6494614c', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which quotation from “The Bet” most effectively illustrates the claim?', '["“Then the banker cautiously broke the seals off the door and put the key in the keyhole.”", "“It struck three o’clock, the banker listened; everyone was asleep in the house and nothing could be heard outside but the rustling of the chilled trees.”", "“The banker, spoilt and frivolous, with millions beyond his reckoning, was delighted at the bet.”", "“When [the banker] got home he lay on his bed, but his tears and emotion kept him for hours from sleeping.”"]'::jsonb, 11, '“The Bet” is an 1889 short story by Anton Chekhov. In the story, a banker is described as being very upset about something: _____'),
  ('3889ab78-3c01-5ee1-bee1-47bbe88dfc1b', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice most effectively uses data from the table to complete the statement?', '["Acropora striata, because its maximum depth of 25 meters is close to but doesn’t reach the mesophotic zone.", "Porites nodifera, because its maximum depth of 15 meters is furthest from the mesophotic zone.", "Agaricia grahamae, because its minimum depth of 20 meters is in the shallow zone.", "Pocillopora meandrina, because its minimum depth of 1 meter is the shallowest of those listed."]'::jsonb, 12, '**Minimum and Maximum Depths of Stony Coral Species in Caribbean and Indo-Pacific Waters**

| Species | Minimum depth (meters) | Maximum depth (meters) |
| Acropora striata | 10 | 25 |
| Porites nodifera | 5 | 15 |
| Pocillopora meandrina | 1 | 27 |
| Agaricia grahamae | 20 | 115 |

Some scientists have suggested that as ocean temperatures rise, many fish and corals found in the shallow zone (less than 30 meters below the surface) could take refuge in the cooler, darker mesophotic zone (30 to 150 meters below the surface). However, it isn’t clear that all such species will be able to tolerate mesophotic conditions. In 2018, Luiz Rocha and colleagues studied stony corals in the two zones in Caribbean and Indo-Pacific waters. Based on the depths at which those corals are now found, the species that seems least suited to a full migration to the mesophotic zone is _____'),
  ('ba8a236a-f600-5434-91be-90990f074fa2', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which finding, if true, would most directly support the second research team’s hypothesis?', '["A study using obstructions that created large vortices in low-visibility conditions found that the intermediate-headed Lobocheilos rhabdoura bumped into the obstructions just as often as the narrow-headed lookdown (Selene vomer) did.", "A study using obstructions that created large vortices in low-visibility conditions found that the lookdown (Selene vomer), which has a relatively narrow head, bumped into more than half of the obstructions.", "A study using obstructions that created large vortices in low-visibility conditions found that the narrow-headed lookdown (Selene vomer) bumped into obstructions more often than the intermediate-headed Lobocheilos rhabdoura did.", "A study using obstructions that created large vortices in low-visibility conditions found that some specimens of the intermediate-headed Lobocheilos rhabdoura bumped into the obstructions more often than other specimens of the same fish did."]'::jsonb, 13, 'Water flowing around an obstruction creates vortices (patterns of swirls) of varying size; by detecting the vortices, fish can determine the size and position of the obstruction. Testing by Yuzo R. Yanagisuru, Otar Akanyeti, and James C. Liao using models of three head shapes—narrow (low ratio of width to length), intermediate, and wide (high ratio of width to length)—showed that for large vortices, fish with intermediate heads would be better able than narrow-headed fish to distinguish between vortices and general turbulence in the water. A second research team has therefore hypothesized that in low-visibility conditions, intermediate-headed fish will be more likely than narrow-headed fish to detect obstructions that create large vortices.'),
  ('79bf7950-1db5-5ea4-9431-c704022cb3e1', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice best describes data from the graph that support the second student’s claim?', '["In all three urban areas shown, the amount of traffic delay per commuter per year was greater in 2000 than in 1990.", "In at least one of the three urban areas shown, the amount of traffic delay was less than 20 hours per commuter per year at one point between 1990 and 2000.", "Throughout the period between 1990 and 2000, the amount of traffic delay per commuter per year was greater in the Allentown-Bethlehem, Pennsylvania, area than in the New York City, New York, area.", "In 1992, the amount of traffic delay in the New York City, New York, area was less than 30 hours per commuter per year."]'::jsonb, 14, '![figure](/q/nov23/001.webp)

In a college course on urban affairs, a student asserts that traffic congestion in the United States increased between 1990 and 2000 mostly in and around very large cities such as New York City, New York. The student claims that not only were smaller areas such as Allentown-Bethlehem, Pennsylvania, and Beaumont, Texas, affected by traffic congestion but in very large cities such as New York City, New York, this congestion also worsened over time.'),
  ('b7b40d3b-13ac-570a-95ed-64aee2253bbd', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice most logically completes the text?', '["users’ intentions to pay for premium streaming services are probably unaffected by factors other than performance expectancy.", "participants who strongly agreed with the statement “Overall, a paid music streaming service is advantageous” were more likely to express loyalty to Spotify than to other streaming services.", "the statement “Overall, a paid music streaming service is advantageous” is not a reliable measure of performance expectancy.", "it may be advantageous for music streaming companies to try to influence the extent to which potential users perceive the use of the premium version to be beneficial."]'::jsonb, 15, 'Mariana Lopes Barata and Pedro Simões Coelho collected data from 324 music-streaming service users to identify factors that influence users to opt for paid (premium) versions of music streaming services, like Spotify. They hypothesized that performance expectancy (how much the use of a service is perceived to benefit the consumer) would be positively correlated with users’ intentions to adopt premium versions. The researchers asked participants to rate statements such as “Overall, a paid music streaming service is advantageous.” They found that, indeed, performance expectancy positively influences the intention to adopt premium streaming service versions, which suggests that _____'),
  ('0fd14286-538d-56bb-a9b5-448e0762a785', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["could their use be better regulated?", "their use could be better regulated.", "their use could be better regulated?", "could their use be better regulated."]'::jsonb, 16, 'Technologies such as microphones and inkjet printers are made using piezoelectric materials, which generate an internal electric field when pressure is applied to them. The toxic nature of some of these materials recently led a team from the University of Sheffield to investigate how _____'),
  ('590730c1-9b54-5ba8-bb7d-fce24598c0df', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are", "have been", "were", "is"]'::jsonb, 17, 'Upper Fruitland Chapter is one of the 110 chapters of the Navajo Nation (Naabeehó Bináhásdzo). The chapter, whose boundaries encompass 83,400 acres, ______ known as Doo alk’ aai in the Navajo language (Diné bizaad).'),
  ('e112b78c-43b5-5f4c-b749-1ae19fc49319', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["study—", "study,", "study:", "study"]'::jsonb, 18, 'While the greater adjutant can be found in places like Hakaluki Haor in Bangladesh and Northern Santuk in Cambodia, more than 80 percent of this endangered stork species is found in Assam, India. There, wildlife biologist Dr. Purnima Devi Barman is on the front lines of conservation efforts that—through community involvement and scientific _____ aim to bring adjutants back from near extinction.'),
  ('c320df6f-2650-5df8-a6d0-a3a7edd556ab', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["has been", "are", "was", "is"]'::jsonb, 19, 'National Heritage Areas like the Arabia Mountain National Heritage Area in Georgia _____ officially designated by the United States Congress as being “unique [and] nationally significant” for their natural, cultural, and historical attributes.'),
  ('34ec78e5-68d2-5c54-ac30-1b9fc3c4081c', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["dislodge in part due to its sheer size,", "dislodge, in part due to its sheer size:", "dislodge, in part due to its sheer size,", "dislodge, in part, due to its sheer size"]'::jsonb, 20, 'On March 23, 2021, a gust of wind wreaked havoc on global trade. Ever Given, an international shipping container vessel, became lodged in Egypt’s Suez Canal, a major shipping route between Europe and Asia. The vessel took six days to _____ it’s as heavy as two thousand blue whales when fully loaded.'),
  ('ce02ab2d-ef4c-5634-a8a3-070bf0e3aebb', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice completes the text with the most logical transition?', '["Alternatively,", "By contrast,", "At that time,", "Additionally,"]'::jsonb, 21, 'Just as the state of Hawaii has a designated state flower, tree, and bird, it also has a state soil: Hilo soil. Hilo is a fitting choice for state soil, in large part because it can be found in abundance across the state. _____ it plays an important role in Hawaii’s agricultural industry and is used to grow a variety of crops, like ginger and taro.'),
  ('1d9292ac-fb71-53c9-bb61-460b0e88c0b4', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'The student wants to emphasize Janaki Ammal’s achievement. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["By crossbreeding the imported sugarcane species Saccharum officinarum with grasses native to India, Ammal succeeded in creating sugarcane hybrids well suited to India’s climate.", "In the 1930s, the Imperial Sugar Cane Institute, which enlisted Ammal, sought to limit dependence on imported sugarcane.", "Ammal was enlisted by the Imperial Sugar Cane Institute at a time when a local variety of sugarcane needed to be produced.", "As part of efforts to breed a local variety of sugarcane, an imported sugarcane species called Saccharum officinarum was crossbred with grasses native to India."]'::jsonb, 22, 'While researching a topic, a student has taken the following notes:

In the 1930s, the Imperial Sugar Cane Institute in India sought to limit the country’s dependence on imported sugarcane.
The institute enlisted botanist Janaki Ammal to breed a local variety of sugarcane.
She crossbred the imported sugarcane species Saccharum officinarum with grasses native to India. She succeeded in creating sugarcane hybrids well suited to India’s climate.'),
  ('c834be96-85a7-5c3c-aceb-75555d15f21d', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'Which choice most effectively uses information from the given sentences to emphasize the size of the sculpture?', '["Richard Serra is an American artist known for his large metal sculptures.", "Cycle—a large metal sculpture by artist Richard Serra—stretches roughly 62 feet wide and 56 feet tall.", "American artist Richard Serra creates large sculptures from metals such as weathering steel.", "Richard Serra’s Cycle is made of weathering steel."]'::jsonb, 23, 'While researching a topic, a student has taken the following notes:

Richard Serra is an American artist.
He is known for his large metal sculptures.
His sculpture Cycle is roughly 62 feet wide and 56 feet tall.
It is made from weathering steel.'),
  ('e37566f6-e7b7-52a8-ae4e-344a67f5e28e', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'The student wants to emphasize a similarity between the two dinosaur fossil specimens. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Both the Tyrannosaurus fossil specimen Jane and the Triceratops fossil specimen Fafnir lived in the Late Cretaceous Period.", "While the Tyrannosaurus fossil specimen Jane is in Rockford, Illinois, the Triceratops fossil specimen Fafnir is in Saint Paul, Minnesota.", "The Burpee Museum of Natural History is home to Jane, a Tyrannosaurus fossil specimen from the Late Cretaceous period.", "Dinosaur fossil specimens can be found at science museums all over the world, including in Rockford, Illinois, and Saint Paul, Minnesota."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

Dinosaur fossil specimens can be found at science museums all over the world.
A dinosaur fossil specimen nicknamed Jane is housed at the Burpee Museum of Natural History in Rockford, Illinois.
Jane, a Tyrannosaurus, lived in the Late Cretaceous period.
A dinosaur fossil specimen nicknamed Fafnir is housed at the Science Museum of Minnesota in Saint Paul, Minnesota.
Fafnir, a Triceratops, lived in the Late Cretaceous period.'),
  ('8486ac47-b150-5478-9d05-dd4b7f0cfe13', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'The student wants to explain what Svetlana Boym writes about in chapter1. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Literary theorist Svetlana Boym outlines the origins and use of the term nostalgia in chapter 1 of her book.", "As Svetlana Boym writes in the seventeenth chapter of her book, “The poetics of nostalgia combines estrangement and human solidarity, affect and reflection.”", "After outlining the origins and use of the term nostalgia, Svetlana Boym goes on to discuss various skeptics’ takes on the concept of nostalgia.", "Svetlana Boym’s The Future of Nostalgia explores the concept of nostalgia from various angles."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

The Future of Nostalgia is a scholarly book by literary theorist Svetlana Boym.
The book explores the concept of nostalgia from various angles.
Chapter 1 outlines the origins and use of the term nostalgia.
Chapter 17 discusses various skeptics’ takes on the concept of nostalgia.
In chapter 17, Boym writes, “The poetics of nostalgia combines estrangement and human solidarity, affect and reflection.”'),
  ('587579e6-3052-5648-a9f7-56ec82c63612', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'The student wants to provide an example of a poem from Morning Haiku. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Included in Sanchez’s poetry book Morning Haiku (2010), “5 love haiku” is a poem written as a sequence of five haiku.", "Sanchez chose to write in the form of the haiku because it helps “maintain memory and dignity.”", "The 2010 poetry book Morning Haiku “celebrates the gifts of life and mourns the deaths of revered African American figures.”", "The poem by Sanchez is written as a sequence of five haiku."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

The poem “5 love haiku” is by African American writer Sonia Sanchez.
It was published in her 2010 poetry book entitled Morning Haiku.
The poem is written as a sequence of five haiku.
According to the book’s publisher, Penguin Random House (PRH), the book “celebrates the gifts of life and mourns the deaths of revered African American figures.”
According to Sanchez, she chose to write in the form of haiku because it helps “maintain memory and dignity.”'),
  ('37268ef1-f6e7-50d3-850c-732f283437cd', '8a949f69-7eab-5adc-93df-152fc756fe1d', 'The student wants to compare the sinuosity of the Fort Nelson and Wadi Al-Hamd rivers. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["While the high-sinuosity Fort Nelson River is located in Canada, the Wadi Al-Hamd River is in Saudi Arabia.", "In both the Fort Nelson and the Wadi Al-Hamd rivers, sinuosity is determined by comparing stream length to valley length.", "The ratio of the Fort Nelson River’s stream length to its valley length is greater than 1.5:1, exceeding that of the Wadi Al-Hamd River.", "By comparing the stream lengths of the Fort Nelson and Wadi Al-Hamd rivers to their valley lengths, one can calculate their sinuosity."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

A river’s stream length is the length of a line that follows along the river path.
A river’s valley length is the length of a straight line drawn from the beginning of the river to the end. The river’s curviness, or sinuosity, is the ratio of the river’s stream length to its valley length. This ratio is less than or equal to 1.5:1 in low-sinuosity rivers and greater than 1.5:1 in high-sinuosity rivers.
The Fort Nelson River in Canada has high sinuosity.
The Wadi Al-Hamd River in Saudi Arabia has low sinuosity.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('347e609e-1f80-5275-99c9-2860a89c9f55', 3, null, '**Choice D is correct.** The sentence explains that new batteries can’t be put in once the old ones no longer work, so the intended word must mean "taken out and new ones put in." "Replaced" precisely expresses that action, and it fits grammatically and logically.
**Choice A is incorrect.** "Rated" refers to an assessment or classification (for example, a battery’s voltage or safety rating), which does not connect to the idea of swapping old batteries for new ones.
**Choice B is incorrect.** "Invented" means created originally; it makes no sense in the context of changing a battery when it stops working.
**Choice C is incorrect.** "Prevented" means stopped from happening. The passage describes an inability to change batteries, not something that is stopped, so this word does not fit.
**Faster approach:** Use the immediate context clue—"new batteries can’t be put in"—to find a synonym that matches that action (here, "replaced").'),
  ('9f2a14a1-9555-5c50-bdf0-6ddface2f53a', 3, null, '**Choice D is correct.** The sentence says Garza creates works "drawing from memories of her childhood in Texas or details of her current surroundings in California," which directly indicates that her work is motivated by those experiences. "Inspired by" precisely captures being motivated or stimulated by direct experience, so it completes the sentence logically and concisely.
**Choice A is incorrect.** "Complimented by" means praised or enhanced by, which does not match the idea that the artist draws creative motivation from experience.
**Choice B is incorrect.** "Uncertain about" contradicts the clear statement that she draws from memories and details; it implies doubt rather than influence.
**Choice C is incorrect.** "Unbothered by" means not disturbed by, which does not express the idea that experience actively informs her work.
**Faster approach:** Look for the phrase that denotes creative influence; eliminate options that imply praise, doubt, or indifference, leaving "inspired by."'),
  ('257164e1-682f-5422-b0b9-4b2b815132a7', 0, null, '**Choice A is correct.** The sentence says genetic research was necessary to establish the relationship between summer squash and the wild Johnny gourd as its ancestor; "confirm" precisely conveys establishing or verifying that ancestral link. It fits grammatically and semantically: researchers used genetic evidence to confirm the ancestor.
**Choice B is incorrect.** "Acquire" means to obtain or gain, which doesn’t make sense here—research doesn’t obtain the wild Johnny gourd as the ancestor.
**Choice C is incorrect.** "Develop" means to cause to grow or evolve; research does not develop an ancestor from a crop.
**Choice D is incorrect.** "Attract" means to draw toward, which is unrelated to establishing lineage or ancestry.
**Faster approach:** Look at the verb "was necessary to" and the phrase "as its ancestor"—the correct word will mean "establish or verify a relationship," so choose "confirm."'),
  ('32fd1f58-7056-5a12-bc15-83aa00940f6e', 1, null, '**Choice B is correct.** The sentence contrasts producing an established classic (low risk) with staging a work by a relatively unknown playwright (higher risk). Saying theaters "would be hesitant to stage" such a work precisely captures reluctance to take that risk, which follows logically from their preference for keeping audiences happy.
**Choice A is incorrect.** "Determined" means resolute or certain to do something, which contradicts the passage’s claim that theaters prefer safe choices and therefore would avoid risky new works.
**Choice C is incorrect.** "Fortunate" means lucky; it doesn’t express an attitude toward taking risks and thus doesn’t fit the contrast in the sentence.
**Choice D is incorrect.** "Surprised" describes an emotional reaction to an event, not a tendency to avoid staging risky works, so it doesn’t complete the sentence logically.
**Faster approach:** Identify the contrast clue (preference for safe, established plays) and choose the word that indicates reluctance or avoidance—so pick the option meaning "reluctant" or "unwilling."'),
  ('871da9b4-e9bf-51f7-ba7d-d0607e12d8af', 1, null, '**Choice B is correct.** The passage emphasizes that Argerich’s performances “appear as if the music is coming to her spontaneously” but that this “apparent ease” is actually “due to a tremendous amount of preparation,” making the central point a cause-and-effect claim about why her playing looks effortless.
**Choice A is incorrect.** Nothing in the passage discusses how Argerich selects which pieces to perform; it focuses on how she plays and prepares.
**Choice C is incorrect.** The passage does not categorize kinds of music or say which pieces she prefers to encounter for the first time; it only describes her general approach.
**Choice D is incorrect.** Although the passage describes her approach—“as if encountering it for the first time”—that detail supports the larger point about why her playing appears effortless rather than serving as the main purpose itself.
**Faster approach:** Look for contrast words (for example, “however,” “despite,” “due to”) to identify cause-and-effect statements that reveal the passage’s main purpose.'),
  ('07ebba00-2466-5ff1-8380-69e9d6c23a95', 3, null, '**Choice D is correct.** The underlined phrase follows "a family of plants" and gives the label applied to that group, so its function is to supply the name used to refer to the related species—the silversword alliance.
**Choice A is incorrect.** The phrase does not list species; it gives a collective name, not specific species names.
**Choice B is incorrect.** The phrase names the group of related plants, not the common name for the single species Dubautia waialealae.
**Choice C is incorrect.** The phrase does not explain any unique trait of Dubautia waialealae; it simply identifies the group to which it belongs.
**Faster approach:** Recognize that phrases set off by commas after a noun often provide a label or appositive—so choose the answer that says it names or identifies the group.'),
  ('c8cc4430-bead-5e03-9ae7-7820d662a10f', 1, null, '**Choice B is correct.** The passage explains why people "crowd into the towns and cities," saying we "love light and life" and that at night, when the country is quiet, people "long for the gas-lit streets, and the sound of human voices." These explicit statements identify the traits and motivations that lead many to choose urban living, so the main purpose is to describe those motivations.
**Choice A is incorrect.** The passage does not focus on feeling isolated in crowded areas; it contrasts crowding in towns with loneliness in the country at night.
**Choice C is incorrect.** The author does appreciate daytime rural beauty but does not caution readers against dismissing it; the emphasis is on why people prefer towns.
**Choice D is incorrect.** The passage does not claim people prefer being alone in the country; it insists people prefer towns, especially at night.
**Faster approach:** Find the sentence that states the author’s main claim (here, why people "crowd into the towns and cities") and choose the answer that restates that claim as the passage’s purpose.'),
  ('92511574-57a6-5516-bcb6-e42a6aba3e36', 1, null, '**Choice B is correct.** Text 1 reports that northern pike ‘‘will have significantly worse outcomes’’ under predicted warming while white-tailed deer ‘‘should be able to withstand the highest predicted warming without much harm,’’ and Text 2 says agencies must use available information to decide which species are most threatened and in need of conservation. Together these statements support prioritizing conservation for the northern pike over the deer.
**Choice A is incorrect.** Neither text argues that collaboration is required to limit temperature rise; they address species impacts and prioritization, not climate mitigation strategies.
**Choice C is incorrect.** While Text 1 is from a tribal group and Text 2 mentions agencies, neither explicitly endorses combining tribal and government resources for pike conservation.
**Choice D is incorrect.** Text 1 implies deer likely won’t require conservation efforts, so immediately starting programs for both is not supported.
**Faster approach:** Identify the species each text flags as threatened and link that to the sentence about agency priorities—choose the option that matches prioritizing the species labeled most at risk.'),
  ('397d3897-7a75-5eb3-ae5b-c1dc437f82ca', 0, null, '**Choice A is correct.** The passage states that "Some historians suggest that Maya mathematicians inherited it from the Olmec civilization," explicitly indicating that the Maya acquired the use of zero from the Olmec. This directly supports choice A.
**Choice B is incorrect.** The passage makes no comparison between how the Maya respected historians versus mathematicians; it only discusses the origin and antiquity of the zero symbol.
**Choice C is incorrect.** There is nothing in the passage that suggests the Maya were secretive about intellectual achievements; the passage focuses on the timeline and possible transmission of the zero symbol.
**Choice D is incorrect.** The passage does not claim the Maya tried to introduce their writing system to other civilizations; it discusses the possibility that they inherited the zero symbol from an earlier culture, the Olmec.
**Faster approach:** For main-idea/detail questions, scan the sentence containing the phrase "some historians suggest" (or similar wording) and base your answer only on that explicit claim to match the choice exactly.'),
  ('93537605-7f5a-5a00-b664-6c4b56ff5435', 3, null, '**Choice D is correct.** The passage describes the energy ladder as a model that explains fuel choice mainly by household income (a single primary factor) and contrasts this with Heltberg’s findings that household fuel use was "heterogeneous, flexible, and influenced by several factors, including the local prices of different fuel sources." That description directly supports the idea that the ladder is "reductive" because it attributes choice primarily to one characteristic while real decisions depend on multiple circumstances.
**Choice A is incorrect.** It says households "ignore" the ladder’s characteristic; the passage does not claim households ignore income, only that other factors also matter.
**Choice B is incorrect.** The passage does not claim Heltberg found fuels used "in equal proportion," only that use was heterogeneous and flexible.
**Choice C is incorrect.** The passage contrasts Costa Rica’s trend with Heltberg’s Guatemala study but does not say the model assumes the same factor everywhere; the key point is that multiple factors—not geographic difference—mediate choice.
**Faster approach:** Look for language in the passage that names the model’s single primary factor (income) and then find wording that lists additional influences; that contrast identifies the answer quickly.'),
  ('787d196f-b1a1-5a8c-a61f-469a6494614c', 3, null, '**Choice D is correct.** The claim says the banker is very upset, and this quotation directly describes his emotional state: "his tears and emotion kept him for hours from sleeping." That explicit mention of tears and inability to sleep shows distress and sorrow, which most effectively illustrates being upset.
**Choice A is incorrect.** Breaking seals and putting a key in a keyhole shows cautiousness or secrecy, not emotional upset; there is no language indicating sorrow or distress.
**Choice B is incorrect.** The description of the quiet house and rustling trees sets a scene and mood but does not state the banker’s emotional reaction, so it does not effectively illustrate that he is upset.
**Choice C is incorrect.** This line says the banker was "delighted at the bet," which expresses pleasure—the opposite of being very upset.
**Faster approach:** Scan choices for explicit emotional words (tears, sorrow, grief) to identify the quotation that directly indicates being upset.'),
  ('3889ab78-3c01-5ee1-bee1-47bbe88dfc1b', 1, null, '**Choice B is correct.** The mesophotic zone begins at 30 meters, so the species least suited to move into that zone would be the one whose recorded maximum depth is farthest from 30 m (i.e., the shallowest maximum). From the table, Porites nodifera has a maximum depth of 15 m, which is 15 meters shallower than the mesophotic threshold and the greatest distance from 30 m among the listed species, indicating it is least likely to already occupy or tolerate mesophotic depths.
**Choice A is incorrect.** Although Acropora striata has a maximum depth of 25 m (just below 30 m), that maximum is closer to the mesophotic zone than Porites nodifera’s 15 m, so it is not the least suited.
**Choice C is incorrect.** Agaricia grahamae does have a minimum depth of 20 m, but its maximum depth is 115 m, well within the mesophotic range, so it is actually well suited to mesophotic conditions.
**Choice D is incorrect.** Pocillopora meandrina’s minimum depth of 1 m indicates it occurs very shallowly, but its maximum depth is 27 m—closer to the mesophotic threshold than Porites nodifera—so it is not the least suited.
**Faster approach:** Compare each species’ maximum depth to 30 m; the species with the smallest maximum depth (farthest below 30 m) is least likely to already occupy or tolerate the mesophotic zone.'),
  ('ba8a236a-f600-5434-91be-90990f074fa2', 2, null, '**Choice C is correct.** The hypothesis predicts that intermediate-headed fish will be better able to detect (and thus avoid) obstructions that create large vortices in low-visibility conditions than narrow-headed fish. If the narrow-headed lookdown bumped into obstructions more often than the intermediate-headed Lobocheilos rhabdoura, that outcome directly demonstrates that the intermediate-headed species detected and avoided obstructions more effectively, supporting the hypothesis.
**Choice A is incorrect.** If both species bumped into obstructions just as often, there is no evidence that intermediate-headed fish are better at detecting obstructions, so this does not support the hypothesis.
**Choice B is incorrect.** That the narrow-headed fish bumped into more than half the obstructions provides no comparison with intermediate-headed fish and thus does not directly support the claim that intermediate-headed fish perform better.
**Choice D is incorrect.** Variation among specimens of the intermediate-headed species alone does not compare intermediate- and narrow-headed fish, so it does not address the hypothesis.
**Faster approach:** Translate the hypothesis into a comparative prediction (intermediate detect/avoid more than narrow). Then pick the answer that shows intermediate outperforming narrow—any direct comparison showing narrow worse than intermediate is the quickest support.'),
  ('79bf7950-1db5-5ea4-9431-c704022cb3e1', 0, null, '**Choice A is correct.** The bar for New York City is higher in 2000 than in 1990, indicating that traffic delay per commuter increased there; the same pattern holds for the other two areas. Because the student’s claim is that congestion worsened over time in very large cities such as New York City, the data showing a higher delay in 2000 than in 1990 for New York City directly support that claim.
**Choice B is incorrect.** Although at least one area (Allentown-Bethlehem) has delays below 20 hours at times, this fact does not specifically support the claim about worsening congestion in very large cities like New York City.
**Choice C is incorrect.** The graph shows Allentown-Bethlehem delays are consistently lower than New York City’s delays, not greater.
**Choice D is incorrect.** The New York City bar in 1992 is well above 30 hours, so that statement is false.
**Faster approach:** To evaluate claims about increase over time, compare the heights of the bars for the relevant area at the start and end years (1990 vs. 2000); if the 2000 bar is higher, the data support a worsening trend.'),
  ('b7b40d3b-13ac-570a-95ed-64aee2253bbd', 3, null, '**Choice D is correct.** The passage reports that performance expectancy "positively influences the intention to adopt premium streaming service versions." That finding implies a practical application: if perceptions of benefit increase adoption intention, then companies could benefit from trying to increase those perceptions (for example, through marketing or product improvements) — which is exactly what choice D states.
**Choice A is incorrect.** The passage only reports a positive relationship, not that performance expectancy is the only factor; claiming other factors are "probably unaffected" is unjustified.
**Choice B is incorrect.** The passage links performance expectancy to intention to adopt premium versions generally, not to loyalty to a specific brand like Spotify, so this inference goes beyond the evidence.
**Choice C is incorrect.** The researchers used that statement as a measure and found the expected relationship; nothing in the passage indicates the statement is unreliable.
**Faster approach:** Look for the choice that expresses the straightforward implication or application of a positive influence (i.e., stakeholders could try to increase that influencing factor) rather than introducing unsupported absolutes or new specifics.'),
  ('0fd14286-538d-56bb-a9b5-448e0762a785', 1, null, '**Choice B is correct.** The sentence contains an indirect question introduced by "how," so the clause should follow normal subject–verb order ("their use could be better regulated") and end with a period, not a question mark. The sentence therefore correctly reads "...investigate how their use could be better regulated."
**Choice A is incorrect.** This choice uses the inverted word order "could their use" and a question mark, which would make the clause a direct question; because it is part of an indirect question introduced by "investigate how," inversion and a question mark are ungrammatical.
**Choice C is incorrect.** Although the clause maintains correct word order, it ends with a question mark; an indirect question requires a period.
**Choice D is incorrect.** This choice both inverts word order (making it a direct question) and ends with a period, creating a mismatch between form and punctuation.
**Faster approach:** Recognize "how" introduces an indirect question; keep normal subject–verb order and use a period.'),
  ('590730c1-9b54-5ba8-bb7d-fce24598c0df', 3, null, '**Choice D is correct.** The sentence’s subject is the singular noun phrase "The chapter," so it requires a singular present-linking verb: "is known as." The relative clause "whose boundaries encompass 83,400 acres" does not change the number of the subject, so "is" provides correct subject-verb agreement and the idiomatic passive construction "is known as."
**Choice A is incorrect.** "Are" is a plural verb and does not agree with the singular subject "The chapter."
**Choice B is incorrect.** "Have been" is plural and present-perfect in form, which mismatches the singular subject and alters tense/aspect unnecessarily.
**Choice C is incorrect.** "Were" is plural (or subjunctive) past tense and does not agree in number with the singular subject; it also changes the time reference without basis.
**Faster approach:** Identify the main subject (here "The chapter") and use subject-verb agreement to pick a singular vs. plural verb; for passive "known as" constructions, the correct simple present linking verb is "is."'),
  ('e112b78c-43b5-5f4c-b749-1ae19fc49319', 0, null, '**Choice A is correct.** The sentence uses a pair of em dashes to set off the parenthetical phrase "through community involvement and scientific study" from the main clause. The first em dash appears before "through," so a matching em dash after "study" is required to close the parenthetical and allow the sentence to continue with "aim to bring...".
**Choice B is incorrect.** A comma after "study" would not properly match the opening em dash and would leave an unclosed parenthetical, creating a punctuation mismatch.
**Choice C is incorrect.** A colon would be grammatically inappropriate here because the clause that follows is not an explanation or list introduced by the preceding phrase, and it would still leave the opening em dash unmatched.
**Choice D is incorrect.** Leaving no punctuation produces an unmatched opening em dash and breaks the sentence structure; the parenthetical must be closed.
**Faster approach:** Identify paired punctuation: if the sentence already has an opening em dash, choose the option that provides the matching closing em dash to maintain balanced punctuation.'),
  ('c320df6f-2650-5df8-a6d0-a3a7edd556ab', 1, null, '**Choice B is correct.** The subject of the sentence, "National Heritage Areas," is plural, so it requires a plural verb form. "Are officially designated" correctly matches the plural subject and produces a grammatically correct general statement about these areas.
**Choice A is incorrect.** "Has been" is singular and does not agree with the plural subject "National Heritage Areas."
**Choice C is incorrect.** "Was" is singular (and past) and therefore does not agree with the plural subject.
**Choice D is incorrect.** "Is" is singular and does not agree with the plural subject.
**Faster approach:** Check subject number (singular vs. plural) and pick the verb form that agrees; here the plural subject requires the plural verb "are."'),
  ('34ec78e5-68d2-5c54-ac30-1b9fc3c4081c', 1, null, '**Choice B is correct.** This option completes the sentence clearly and conforms to the conventions of Standard English. It uses a comma before the phrase "in part due to its sheer size," which correctly separates this explanatory clause from the main clause. The colon at the end indicates that an explanation follows, fitting well with the context of the sentence.
Here’s a breakdown of why each option is correct or incorrect:
**Choice A:** "dislodge in part due to its sheer size," lacks necessary punctuation. The absence of a comma leads to confusion about the relationship between the parts of the sentence.
**Choice B:** "dislodge, in part due to its sheer size:" is correct as it uses the necessary comma to separate the explanatory phrase and ends appropriately with a colon, indicating that an elaboration follows.
**Choice C:** "dislodge, in part due to its sheer size," also has a comma, but it ends with a comma instead of a period or colon, making the sentence seem incomplete and grammatically incorrect. **Choice D:** "dislodge, in part, due to its sheer size" includes unnecessary commas around "in part," which disrupts the flow of the sentence and creates a confusing break in the thought.'),
  ('ce02ab2d-ef4c-5634-a8a3-070bf0e3aebb', 3, null, '**Choice D is correct.** The sentence before the blank gives one reason Hilo soil is a fitting state soil (its abundance); the next sentence offers a second, related reason (its agricultural importance). A transition that adds information—"Additionally,"—is the most logical and coherent link between these two supportive statements.
**Choice A is incorrect.** "Alternatively," introduces a different option or substitute, which does not fit because the second clause is not proposing an alternative reason but giving another supporting reason.
**Choice B is incorrect.** "By contrast," signals a difference or opposition; here the second clause reinforces the positive case for Hilo soil rather than contrasting with the first clause.
**Choice C is incorrect.** "At that time," denotes a temporal relation, but the sentences present distinct reasons rather than describing events occurring simultaneously, so a time marker is inappropriate.
**Faster approach:** Identify whether the second sentence adds, contrasts, alternatives, or gives time; then choose the transition that matches—here both sentences provide additional reasons, so pick an adding transition like "Additionally."'),
  ('1d9292ac-fb71-53c9-bb61-460b0e88c0b4', 0, null, '**Choice A is correct.** It directly credits Janaki Ammal with the specific action (crossbreeding Saccharum officinarum with native grasses) and the successful outcome (creating hybrids well suited to India’s climate), which most clearly emphasizes her achievement using the notes’ details.
**Choice B is incorrect.** It emphasizes the institute’s goals and context rather than Ammal’s personal accomplishment, so it does not highlight her achievement.
**Choice C is incorrect.** It notes that Ammal was enlisted when a local variety was needed but omits her specific work and the successful result, failing to emphasize her achievement.
**Choice D is incorrect.** It describes the crossbreeding but uses passive phrasing that does not attribute the accomplishment to Ammal and does not state the successful outcome, so it downplays her achievement.
**Faster approach:** Look for the option that names the person, the specific action they took, and the successful result—those three elements reliably emphasize an achievement.'),
  ('c834be96-85a7-5c3c-aceb-75555d15f21d', 1, null, '**Choice B is correct.** This sentence uses the specific details from the notes to emphasize the sculpture’s size by giving precise dimensions: “roughly 62 feet wide and 56 feet tall.” Including the name of the work and the artist keeps the sentence clear while foregrounding the large scale with concrete numbers.
**Choice A is incorrect.** Although it mentions that Serra is known for “large metal sculptures,” it does not give any specific size information and so is less effective at emphasizing the sculpture’s magnitude.
**Choice C is incorrect.** It focuses on the materials Serra uses rather than the size, and it generalizes about his work instead of highlighting the dimensions of Cycle.
**Choice D is incorrect.** It notes the material (weathering steel) but omits any reference to the sculpture’s dimensions, so it does not emphasize size.
**Faster approach:** For questions asking which choice emphasizes size, pick the option that gives specific numeric dimensions or concrete size descriptors rather than vague or material-focused wording.'),
  ('e37566f6-e7b7-52a8-ae4e-344a67f5e28e', 0, null, '**Choice A is correct.** The notes state that Jane (a Tyrannosaurus) and Fafnir (a Triceratops) both "lived in the Late Cretaceous period," so sentence A clearly emphasizes the similarity between the two specimens by citing that shared time period.
**Choice B is incorrect.** That sentence emphasizes a difference in location (Rockford vs. Saint Paul) rather than a similarity between the two specimens.
**Choice C is incorrect.** This sentence focuses only on Jane and provides no information comparing Jane with Fafnir, so it does not emphasize a similarity between the two specimens.
**Choice D is incorrect.** Although it mentions both locations, it makes a general claim about museums worldwide and does not highlight a specific similarity between Jane and Fafnir (such as the period in which they lived).
**Faster approach:** Scan the notes for a detail stated for both items (a shared trait) and pick the choice that directly names that shared trait—here, the Late Cretaceous period.'),
  ('8486ac47-b150-5478-9d05-dd4b7f0cfe13', 0, null, '**Choice A is correct.** The notes state explicitly that "Chapter 1 outlines the origins and use of the term nostalgia," so saying that Boym "outlines the origins and use of the term nostalgia in chapter 1" accurately and directly reports the relevant information about that chapter.
**Choice B is incorrect.** It quotes material from chapter 17, not chapter 1, so it does not explain what Boym writes about in chapter 1.
**Choice C is incorrect.** Although it mentions that she outlines the term, it adds information about a later chapter; the question asks specifically for what she writes about in chapter 1, so the extra detail about chapter 17 makes this less direct and less focused than Choice A.
**Choice D is incorrect.** This statement describes the book generally but does not specify what Boym writes in chapter 1 about the origins and use of the term "nostalgia."
**Faster approach:** Locate the note that names the chapter and restate that exact clause—use the brief, specific note about chapter 1 rather than broader or off-topic notes.'),
  ('587579e6-3052-5648-a9f7-56ec82c63612', 0, null, '**Choice A is correct.** It directly identifies “5 love haiku” as a poem in Sonia Sanchez’s 2010 book Morning Haiku and specifies its form (a sequence of five haiku), which uses the student’s notes to give a clear, relevant example of a poem from that book.
**Choice B is incorrect.** Although it quotes Sanchez’s reason for using the haiku form, it does not indicate that the poem is in Morning Haiku or name the poem, so it fails to provide an example of a poem from the book.
**Choice C is incorrect.** This describes the book’s theme but does not identify or give an example of a specific poem from Morning Haiku.
**Choice D is incorrect.** It states the poem’s form but does not connect the poem to Morning Haiku or give the poem’s title, so it is less effective than choice A.
**Faster approach:** Choose the option that explicitly names the poem and the book and gives a specific detail about the poem’s form or placement—this directly accomplishes the task of providing an example.'),
  ('37268ef1-f6e7-50d3-850c-732f283437cd', 2, null, '**Choice C is correct.** The notes state that a river has high sinuosity when the stream-to-valley length ratio is greater than 1.5:1 (and low sinuosity when that ratio is less than or equal to 1.5:1). They also identify the Fort Nelson River as high sinuosity and the Wadi Al-Hamd River as low sinuosity. Therefore the Fort Nelson River’s ratio is greater than 1.5:1 and exceeds the Wadi Al-Hamd River’s ratio.
**Choice A is incorrect.** It only gives locations of the rivers and does not compare their sinuosity.
**Choice B is incorrect.** Although it correctly states how sinuosity is determined, it does not compare the two rivers’ sinuosity values.
**Choice D is incorrect.** It describes a method for calculating sinuosity but does not use the given information that Fort Nelson is high and Wadi Al-Hamd is low to compare them.
**Faster approach:** Use the explicit labels “high” (>1.5:1) and “low” (≤1.5:1) given for the two rivers to directly conclude which ratio is larger.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Nov 2023 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('3e80bb51-f811-50f3-af17-474109be6f25', 'PeaklyTest Nov 2023 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Nov 2023 PeaklyTest · 27 questions · 32 minutes', 32, 321, true, 'PeaklyTest Nov 2023 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('742101f7-64aa-51d8-a032-a27a420b8fde', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text with the most logical and precise word or phrase?', '["cheap", "common", "rapid", "difficult"]'::jsonb, 1, 'Excavating a dilophosaur fossil is a ______ process, since it can take weeks or even months of hard, physically tiring work to clear away the dirt and rock covering the specimen.'),
  ('33d0f678-6c56-5d02-8834-b39951ede7ab', '3e80bb51-f811-50f3-af17-474109be6f25', 'As used in the text, what does the word “tell” most nearly mean?', '["Judge", "Urge", "Adore", "Teach"]'::jsonb, 2, 'The following text is from Lilliam Rivera’s 2020 novel Never Look Back. The text describes the narrator looking around his father’s apartment.
Pops’s pride and joy is his wall of towering bookshelves. He once said you can <u>tell</u> a man’s worth by the number of books he owns. I guess this means Pops is overflowing with riches because ever since I can remember I was never without a book within reach.

©2020 by Lilliam Rivera'),
  ('e7b341d8-ceb2-52d7-a95e-168b8d6f096b', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text with the most logical and precise word or phrase?', '["exclusive to", "evocative of", "typical for", "superseded by"]'::jsonb, 3, 'The minor planet 1061 Paeonia was named after the plant genus that includes peonies. But most minor planets are given only an identification number, both because there are over 500,000 such bodies known at present and because any name chosen needs to be _____ that body: no two minor planets are allowed to have the same name.'),
  ('43415482-9db9-5b4d-8479-81a478daa130', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text with the most logical and precise word or phrase?', '["pervasive", "credible", "assertive", "profound"]'::jsonb, 4, 'Text corpora such as the British National Corpus are enormous collections of electronically stored texts that can be used for empirical testing of hypotheses regarding how _____ a word is in spoken and written English. For instance, one might have a guess about the incidence of the word “world,” but only an analysis of a corpus can prove that “world” is the eighth most commonly used noun.'),
  ('103b346a-e546-5353-8029-82b2ababc5eb', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice best states the main purpose of the text?', '["To compare basketball with other sports.", "To provide details of how to play basketball.", "To state how players will be chosen for the basketball team.", "To explain why the narrator thinks she might make the basketball team."]'::jsonb, 5, 'The following text is adapted from Jean Webster’s 1912 novel Daddy-Long-Legs. The narrator is a young college student writing letters detailing her weekly experiences.

[The college is] organizing the Freshman basket-ball team and there’s just a chance that I shall make it. I’m little of course, but terribly quick and wiry and tough. While the others are hopping about in the air, I can dodge under their feet and grab the ball.'),
  ('ea65b787-2961-5bf2-b4a1-3b4a7635dda8', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["The sentence introduces a term that is used in the discussion that follows.", "The sentence explains the unique nature of the researchers’ hypothesis.", "The sentence summarizes the debate presented in the text.", "The sentence identifies the location of a bone in felines."]'::jsonb, 6, 'Why do jungle cats purr but leopards roar? Researchers hypothesize that this difference between the two feline species may be partly due to a U-shaped bone in their throats. <u>This bone is called the hyoid.</u> Jungle cats, which are much smaller than leopards, have a rigid hyoid that rumbles when the cat’s larynx vibrates, resulting in a purr. By contrast, leopards have a somewhat flexible hyoid, and the bone is attached to the skull with a stretchy ligament that jungle cats lack. These traits allow leopards and most other species of big cats to roar. The same traits may also prevent most big cats from purring.'),
  ('772252c2-5b8f-5a08-88df-2a1419679647', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice best states the main idea of the text?', '["Unlike primates, octopuses are exceptionally skillful at using different tools.", "There are many myths about tool use that researchers are starting to challenge.", "Animals find it difficult to use objects as tools.", "Contrary to long-held beliefs, primates aren’t the only animals to use tools."]'::jsonb, 7, 'Animals use many objects as tools to achieve goals more easily. Such goals include grooming, finding food, and protecting themselves. For a long time, people thought tool use was unique to primates. Octopuses and other animals, though, have busted the myth that tool use requires hands. Inventively, octopuses use two halves of a seashell to provide protection or a place to hide. Greater vasa parrots also get creative. They use date pits to grind seashells into calcium powder.'),
  ('70b01d69-48ea-5104-8a5a-b32c36018718', '3e80bb51-f811-50f3-af17-474109be6f25', 'According to the text, how did Hooks and Ward initially meet?', '["Harrison introduced Hooks to Ward at a performance of The Great Macdaddy.", "Hooks and Ward attended the same performance of The Great Macdaddy.", "Hooks and Ward participated in the same workshop at NEC.", "Hooks and Ward were both actors in a production of A Raisin in the Sun."]'::jsonb, 8, 'The groundbreaking Negro Ensemble Company (NEC), founded in 1967, produced Paul Carter Harrison’s award-winning play The Great Macdaddy in 1974. The company was cofounded by Robert Hooks, an actor, producer, and activist, and actor and playwright Douglas Turner Ward, who had met while performing in a 1960 touring production of Lorraine Hansberry’s play A Raisin in the Sun. They shared a vision of a theater company that would nurture and showcase the work of Black theater professionals. Since its beginning, NEC has provided a forum for the voices of Harrison and other Black playwrights through workshops and performances.'),
  ('589d5cc8-c33e-5744-b0d3-c096b6c65645', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice most effectively uses data from the table to complete the statement?', '["the number of cars produced increased but the number of companies producing cars decreased.", "both the number of cars produced and the number of companies producing cars remained unchanged.", "the number of cars produced decreased but the number of companies producing cars remained unchanged.", "both the number of cars produced and the number of companies producing cars increased."]'::jsonb, 9, '**Annual Car Production in the United States, 1910-1925**

| Year | Number of cars produced | Number of companies producing cars |
| 1910 | 123,990 | 320 |
| 1915 | 548,139 | 224 |
| 1920 | 1,651,625 | 197 |
| 1925 | 3,185,881 | 80 |

A student is using the table as part of a social studies class presentation on the US auto industry in the early twentieth century. The student notes that, according to the table, from 1910 to 1925 _____'),
  ('95564c38-d80e-5221-b393-a3cfe7705397', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which finding, if true, would most directly support the underlined claim?', '["Most people spend about three minutes viewing The Card Game at the museum and only about one minute viewing it online.", "The Card Game isn’t the only work of art by Jacob Lawrence that has been put online.", "Most people who go to museums in Savannah are visiting from other places.", "More than one museum has works of art by Jacob Lawrence in its full collection."]'::jsonb, 10, 'The Card Game is a painting by Jacob Lawrence, dated 1953. It’s part of the full collection of the SCAD Museum of Art in Savannah, Georgia. A digital image of it can also be found in an online collection. In a paper, a student claims that <u>people usually spend more time viewing a work of art in a museum than they</u> <u>do online.</u>'),
  ('2c861294-2bd3-5625-b393-f49984924ac0', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice most logically completes the text?', '["the measures aimed at protecting birds will likely also minimize most of the effects on arthropods.", "the severity of the effects of noise on different species of birds can differ significantly.", "the effects of noise on birds have been less extensively documented than the effects on arthropods have.", "the measures intended to protect birds can sometimes have adverse effects on arthropods."]'::jsonb, 11, 'Research such as the 2010 study of arthropods by Alvin Aaden Yim-Hol Chan and colleagues has shown that noise from human activity, like traffic on a busy highway, has significant effects on animals, and many governments require studies of the potential noise effects on wildlife before approving highway construction projects. A report on one such study proposed many more actions to mitigate the effects on birds in the area than it did to mitigate the effects on arthropods in the area. Despite the lack of focus on measures specifically for arthropods, conservationists were satisfied that the proposed mitigations were sufficient to protect all the wildlife in the area because _____'),
  ('3c8ef8ff-a4e5-5562-82bb-2d912dc17715', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice most logically completes the text?', '["not all ships with three decks were ranked as first-rate ships.", "all ships with at least 98 cannons were ranked as first-rate ships.", "the Dreadnought had between 850 and 875 crewmen.", "the Caledonia needed a crew larger than 875 people in order to operate efficiently."]'::jsonb, 12, 'In the early 19th century, ships in the British Royal Navy were ranked based on military strength. The system considered the number of a ship’s cannons and decks. “First-rate” was the highest ranking and “sixth-rate” was the lowest ranking followed by unranked ships. This ranking determined the size of a ship’s crew; first-rate ships had between 850 and 875 crewmen, while lower-ranked ships had fewer. Two of the ships in the British Royal Navy from this period were the Dreadnought (98 cannons and three decks) and the Caledonia (120 cannons and three decks). Of these two, only the Caledonia was ranked a first-rate ship. It can therefore be concluded that _____'),
  ('5733de3f-4427-5906-941e-4d6e0c2db5df', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice most logically completes the text?', '["factors other than Austria’s political structure contributed to the country’s inflation rate exceeding that of Cameroon in 2017.", "the 2017 difference between Austria’s inflation rate and Cameroon’s inflation rate is primarily but not exclusively attributable to the different levels of intranational income inequality in the two countries.", "international indices may have underestimated the strength of Austria’s democratic institutions relative to Cameroon’s.", "inflation in Austria in 2017 would have been higher if Austria’s government had less control over the economy."]'::jsonb, 13, 'Austria, which, according to international indices, has relatively strong democratic institutions and low intranational income inequality, experienced an inflation rate of 2.08% in 2017, whereas Cameroon, which shows the opposite pattern on such indices, had an inflation rate of only 0.64% that year. Such a comparison may seem consistent with the theoretical critique that by diluting control over the economy, democratic institutions inhibit states’ ability to counteract inflationary pressures, but when Raj Desai et al. examined democratic strength, intranational inequality, and inflation in more than 100 countries, they found that democratic strength, if associated with low inequality, restrains inflationary pressures, which would suggest that _____'),
  ('0cf34666-d92c-54d9-8c8a-fd0f7a3f6cfe', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["compiled,", "compiled", "compiled;", "compiled:"]'::jsonb, 14, 'On February 1, 2018, Florida-based researchers Martha A. Scholl, Maoya Bassiouni, and Angel J. Torres-Sánchez _____ compiled climate data from several sites in Puerto Rico’s Luquillo Mountains. At 8:30 a.m., the air temperature was 16°C at site CC1, the site with the highest elevation, and it had shifted to 16.8°C by 11:00 p.m.'),
  ('563fc76c-baf2-57fb-a903-4f423ca2105a', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is", "is;", "is:", "is,"]'::jsonb, 15, 'Summer is typically thought of as a sweltering season. However, the city of Ljubljana has rather cool summers. There, the average summer temperature _____ just 66.7 degrees Fahrenheit.'),
  ('6a959cb4-e879-5db6-810e-43db64e3dbfa', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["it was invented by an author?", "it was invented by an author.", "was it invented by an author.", "wasn’t it invented by an author."]'::jsonb, 16, 'What is the origin of the word “blatant”? Interestingly, _____ It first appears in the poem The Faerie Queene by English author Edmund Spenser.'),
  ('624b413c-4906-5f8b-91c0-1ba1f230da56', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["used", "to have used", "to use", "using"]'::jsonb, 17, 'In 1929, Edwin Herbert Land invented a polarizing filter that was featured in a number of products, from sunglasses to 3D movies. A decade later, Land _____ his technology to invent the world’s first instant camera, the Polaroid Land camera.'),
  ('1742591d-44e8-5a8c-bcfe-d3867a960dda', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["instrument:", "instrument", "instrument—", "instrument."]'::jsonb, 18, 'A harpsichord may look just like a piano, but the difference between the two instruments is easy to hear. When a harpsichord’s keys are pressed, the strings inside the _____ are plucked not struck. Which choice completes the text so that it conforms to the conventions of Standard English?'),
  ('a5e98b7a-2cdb-5710-a970-a01bf4f44dc0', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["do they affect our weather.", "they do affect our weather.", "do they affect our weather?", "they do affect our weather?"]'::jsonb, 19, 'In forecasting weather events, meteorologists sometimes discuss the role of atmospheric rivers. What are atmospheric rivers, and how _____ Part of the water cycle, atmospheric rivers are narrow channels of moisture moving through the atmosphere. In certain conditions, these “rivers” can release some of their moisture as precipitation.'),
  ('265f317f-a8a6-5789-8b80-cbe3ebcb65cf', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["threefold; expanding", "threefold expanding", "threefold. expanding", "threefold: expanding"]'::jsonb, 20, 'Included in Every Day: Selections from the Collection, a 2019 group exhibition at the Baltimore Museum of Art in Maryland, was the work of multimedia artist Lorna Simpson. The impact of Simpson’s work is _____ the horizons of conceptual photographic art, challenging conventional notions of race, gender, history, and memory, and shedding light on the experience of African American women in contemporary society.'),
  ('c89cf1b2-8731-5fe2-a509-360daaaefda2', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text with the most logical transition?', '["In any case,", "Earlier,", "In fact,", "Instead,"]'::jsonb, 21, 'In eastern Mexico, Monument 61 and Monument 1 are the names given to two massive human head statues that were left behind by the ancient Olmec civilization. Both statues are made of stone and are extremely heavy. _____ they each weigh more than 5 tons!'),
  ('e52d9843-ba9b-5b69-80e9-c64b3a7881cb', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text with the most logical transition?', '["Instead,", "For example,", "Later,", "In other words,"]'::jsonb, 22, 'In 2014, Nestor Gomez won his first-ever storytelling competition, relating a tale about his life as a Guatemalan immigrant living in Chicago. _____ in 2017, Gomez created the show 80 Minutes Around the World as a platform for others to share stories about their immigration experiences.'),
  ('81f13ead-385c-52cb-99f0-097d94ab4d3b', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text with the most logical transition?', '["Fittingly,", "Conversely,", "Nowadays,", "Still,"]'::jsonb, 23, 'In his essay “Of Friendship,” French philosopher Michel de Montaigne explores a relatively light subject, but he addresses heavier fare in “Of the Uncertainty of Our Judgment.” Regardless of subject matter, Montaigne works to question his own perspective throughout his essays. _____'),
  ('84fe00cf-a693-5322-b870-5a4390d5c15b', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice completes the text with the most logical transition?', '["Fittingly,", "Granted,", "More often,", "For example,"]'::jsonb, 24, 'Julius LeMoyne was an outspoken abolitionist whose Pennsylvania home was a stop on the Underground Railroad (the network of people and places that some enslaved people used to escape to freedom). It was relatively rare for supporters of the railroad to be secretive about their antislavery views. _____ they were vocal abolitionists like LeMoyne.'),
  ('5b556f41-e50c-547c-97a6-fae2bafdc3cd', '3e80bb51-f811-50f3-af17-474109be6f25', 'Which choice most effectively uses information from the given sentences to emphasize when she collected both of the samples?', '["Thousands of botanical samples collected by Ynés Mexía can now be found in one place: online at the C.V. Starr Virtual Herbarium.", "On May 3 in 1930, Ynés Mexía added a new specimen to her growing collection of botanical samples: Achyrocline vauthieriana of the Asteraceae family.", "While both specimens collected by Ynés Mexía are members of the same family, Achyrocline vauthieriana was found in Minas Gerais and Vernonia liatroides was found in Jalisco.", "**Ynés Mexía collected a sample of Achyrocline vauthieriana in May of 1930, after collecting** **Vernonia liatroides in February of 1927.**"]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Ynés Mexía was a Mexican American botanist.
Between 1917 and 1938, she collected over 150,000 botanical samples throughout the Americas. She collected a sample of Achyrocline vauthieriana in Minas Gerais, Brazil, on May 3, 1930. She collected a sample of Vernonia liatroides in Jalisco, Mexico, on February 14, 1927. These specimens are members of the Asteraceae family.
They can now be viewed online at the C.V. Starr Virtual Herbarium.'),
  ('282175e2-b74d-5cf2-81f1-47efe215d1c4', '3e80bb51-f811-50f3-af17-474109be6f25', 'The student wants to emphasize the mass of Sirius A. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The mass of stars, like Proxima Centauri, can be described in units called solar masses.", "In astronomy, the mass of stars can be described in units called solar masses, and one solar mass is roughly equal to the mass of the Sun.", "The Sun is more massive than Proxima Centauri, which has a mass of 0.122 solar masses.", "With a mass of 2.063 solar masses, Sirius A is more massive than the Sun."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

In astronomy, the mass of stars can be described in units called solar masses.
One solar mass is roughly equal to the mass of the Sun.
The mass of the star Proxima Centauri is 0.122 solar masses.
The mass of the star Sirius A is 2.063 solar masses.'),
  ('71fd4fe4-29fb-5a6c-89c5-d64477bd208f', '3e80bb51-f811-50f3-af17-474109be6f25', 'The student wants to emphasize a similarity between the two TV programs. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["A prime example of the slow TV genre can be seen in All Aboard! The Sleigh Ride, a 2-hour British TV documentary program documenting a sleigh ride along an arctic postal route.", "While All Aboard! The Sleigh Ride depicts a sleigh ride along an arctic postal route, Monsen: Minutt for Minutt depicts a hike from Stigstuv to Rauhelleren in Norway.", "Compared to the 5-hour-long Monsen: Minutt for Minutt, the slow TV program All Aboard! The Sleigh Ride is relatively short, at 2 hours.", "Documenting ordinary events in real time, All Aboard! The Sleigh Ride and Monsen: Minutt for Minutt are both documentary programs in the slow TV genre."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Documentary TV programs in the slow TV genre consist of uninterrupted broadcasts of ordinary events in real time.
All Aboard! The Sleigh Ride (running time: 2 hours) is a British slow TV program that aired in 2015. It documented a sleigh ride along an arctic postal route.
Monsen: Minutt for Minutt (running time: 5 hours) is a Norwegian slow TV program that aired in 2020. It documented a hike from Stigstuv to Rauhelleren in Norway.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('742101f7-64aa-51d8-a032-a27a420b8fde', 3, null, '**Choice D is correct.** The passage describes a task that "can take weeks or even months of hard, physically tiring work," so the best word to complete the sentence is one that matches that description; "difficult" precisely conveys that the process requires effort and is not easy.
**Choice A is incorrect.** "Cheap" refers to low cost; nothing in the sentence addresses expense, so this choice is irrelevant.
**Choice B is incorrect.** "Common" means frequent or typical; the sentence instead emphasizes the effort and duration required, not how often such excavations occur.
**Choice C is incorrect.** "Rapid" means fast, but the sentence states the work can take "weeks or even months," directly contradicting the idea of being quick.
**Faster approach:** Match the underlined clue words "weeks or even months" and "hard, physically tiring" to answer choices—eliminate any choice that implies speed, frequency, or cost, leaving "difficult."'),
  ('33d0f678-6c56-5d02-8834-b39951ede7ab', 0, null, '**Choice A is correct.** In the sentence “you can <u>tell</u> a man’s worth by the number of books he owns,” “tell” means to determine or judge something about a person based on evidence; here the number of books is evidence of a man’s worth.
**Choice B is incorrect.** “Urge” would mean to encourage someone to do something, which does not fit the sense of using books as evidence to form an opinion.
**Choice C is incorrect.** “Adore” means to love greatly; the sentence is not expressing love for the man but assessing him.
**Choice D is incorrect.** “Teach” means to instruct; the context is about inferring a man’s value from his books, not instructing him.
**Faster approach:** Use context: if X is judged “by” Y, then the verb means to evaluate or judge—choose the answer meaning “judge.”'),
  ('e7b341d8-ceb2-52d7-a95e-168b8d6f096b', 0, null, '**Choice A is correct.** The sentence explains that no two minor planets may share the same name, so any name must be uniquely assigned to a single body. "Exclusive to" precisely conveys that uniqueness: a name must be exclusive to that body.
**Choice B is incorrect.** "Evocative of" means suggesting or calling to mind something, which does not address the requirement that a name be unique to a single minor planet.
**Choice C is incorrect.** "Typical for" indicates commonness or representativeness, the opposite of the uniqueness the sentence requires.
**Choice D is incorrect.** "Superseded by" means replaced by, which is unrelated to the idea that a name must belong only to one body.
**Faster approach:** Focus on the clause "no two...allowed to have the same name" and choose the option that signals uniqueness ("exclusive to").'),
  ('43415482-9db9-5b4d-8479-81a478daa130', 0, null, '**Choice A is correct.** The passage discusses using corpora to measure how common a word is in spoken and written English, so a word meaning "widespread" or "commonly occurring" fits best. "Pervasive" precisely conveys that sense: it describes something that occurs throughout a language or is widely distributed.
**Choice B is incorrect.** "Credible" means believable or plausible, which does not relate to frequency or distribution in language use.
**Choice C is incorrect.** "Assertive" describes a confident manner, not how often a word appears.
**Choice D is incorrect.** "Profound" means deep or intense in significance, which is unrelated to a word’s incidence or commonness.
**Faster approach:** Quickly substitute each choice into the sentence and pick the one whose meaning matches "frequency/commonness"—that immediately yields "pervasive."'),
  ('103b346a-e546-5353-8029-82b2ababc5eb', 3, null, '**Choice D is correct.** The narrator states that there’s a chance she’ll make the Freshman basketball team and immediately gives reasons—she’s small, quick, wiry, and can dodge under others to grab the ball—so the passage’s main purpose is to explain why she thinks she might make the team.
**Choice A is incorrect.** The passage does not compare basketball with other sports; it only describes the narrator’s abilities in relation to teammates during play.
**Choice B is incorrect.** The passage gives no instructions or rules about how to play basketball; it only describes one player’s quickness and dodging ability.
**Choice C is incorrect.** The text does not explain the selection process or criteria for choosing players; it merely offers the narrator’s reasons for believing she could be chosen.
**Faster approach:** Quickly identify the narrator’s main claim and look for the supporting detail that explains or justifies that claim—if the passage gives reasons for a statement, the purpose is to explain why.'),
  ('ea65b787-2961-5bf2-b4a1-3b4a7635dda8', 0, null, '**Choice A is correct.** The underlined sentence names the specific bone—"the hyoid"—so that the passage can refer to it in the explanation that follows. It functions as an introduction of terminology used to compare jungle cats and leopards (rigid versus flexible hyoid), which supports the passage’s causal explanation of purring versus roaring.
**Choice B is incorrect.** The sentence does not comment on the hypothesis’s uniqueness; it simply provides a label for the bone rather than qualifying the hypothesis.
**Choice C is incorrect.** The passage does not present a debate to be summarized; the sentence does not summarize conflicting views.
**Choice D is incorrect.** The sentence names the bone but does not specify its location in felines; it only gives the bone’s name.
**Faster approach:** Look for a brief definitional sentence following a concept; such sentences typically introduce a term used later, so choose the ‘‘introduces a term’’ option.'),
  ('772252c2-5b8f-5a08-88df-2a1419679647', 3, null, '**Choice D is correct.** The passage explains that people once thought tool use was unique to primates but then gives examples (octopuses using seashell halves; greater vasa parrots using date pits) that contradict that belief, so the main idea is that primates aren’t the only animals to use tools.
**Choice A is incorrect.** The passage does not claim octopuses are exceptionally more skillful than primates; it only gives octopuses as an example of non-primate tool use.
**Choice B is incorrect.** While the passage challenges a specific belief about tool use, it does not discuss many myths or the broader process of researchers challenging myths.
**Choice C is incorrect.** The passage states the opposite: animals do use objects as tools and even inventively so, not that they find it difficult.
**Faster approach:** Look for a sentence that summarizes the passage’s purpose (often the thesis) and match that to the answer choices; here the sentence about people thinking tool use was unique to primates directly points to choice D.'),
  ('70b01d69-48ea-5104-8a5a-b32c36018718', 3, null, '**Choice D is correct.** The passage states that Hooks and Ward "had met while performing in a 1960 touring production of Lorraine Hansberry’s play A Raisin in the Sun," which directly says they were both actors in that production.
**Choice A is incorrect.** The passage names Paul Carter Harrison in a different context and does not say Harrison introduced Hooks to Ward; it specifically says Hooks and Ward met while performing together.
**Choice B is incorrect.** The passage does not say they attended the same performance of The Great Macdaddy; it says they met in a 1960 touring production of A Raisin in the Sun, a different play.
**Choice C is incorrect.** Although the NEC later provided workshops, the passage indicates their initial meeting occurred during a production of A Raisin in the Sun, not at an NEC workshop.
**Faster approach:** Scan for the sentence that describes how they "met"—the immediate clause gives the direct answer (look for verbs like "met" or "performing").'),
  ('589d5cc8-c33e-5744-b0d3-c096b6c65645', 0, null, '**Choice A is correct.** The table shows that car production rose from 123,990 in 1910 to 3,185,881 in 1925 (an increase), while the number of companies producing cars fell from 320 in 1910 to 80 in 1925 (a decrease), so the statement accurately describes both trends.
**Choice B is incorrect.** The data show clear change in both quantities: production and number of companies do not remain the same.
**Choice C is incorrect.** Production did not decrease; it increased markedly between 1910 and 1925.
**Choice D is incorrect.** Although production increased, the number of companies decreased rather than increased.
**Faster approach:** Compare the 1910 and 1925 cells for each column directly—if the later value is larger, it increased; if smaller, it decreased. This quick pairwise check works for every table-based trend question.'),
  ('95564c38-d80e-5221-b393-a3cfe7705397', 0, null, '**Choice A is correct.** The underlined claim says people usually spend more time viewing a work of art in a museum than they do online; choice A gives a direct comparison of viewing times for The Card Game (three minutes in the museum vs. one minute online), which directly supports the claim for that work and illustrates the general pattern the student asserts.
**Choice B is incorrect.** That fact only indicates multiple works by the same artist are online; it says nothing about how long people view works in either setting.
**Choice C is incorrect.** Whether museum visitors are from other places concerns visitor origin, not viewing durations in person versus online.
**Choice D is incorrect.** Knowing that more than one museum has Lawrence’s works in its collection addresses distribution of works across museums, not how long viewers spend looking at them in person versus online.
**Faster approach:** Look for an answer that gives a direct, quantitative comparison of time spent viewing in the two settings; eliminate choices that address unrelated facts (location, number of works) rather than viewing duration.'),
  ('2c861294-2bd3-5625-b393-f49984924ac0', 0, null, '**Choice A is correct.** The passage says conservationists were satisfied despite fewer arthropod-specific measures; the only logical reason for that satisfaction is that the bird-focused mitigations would also reduce the noise-related harms to arthropods, so protecting birds effectively protects other wildlife as well.
**Choice B is incorrect.** That statement, about variability in severity for different bird species, does not explain why conservationists would be satisfied that bird measures protect arthropods.
**Choice C is incorrect.** If effects on birds were less documented, that would not justify confidence that bird-focused measures suffice for arthropods; it would undermine confidence instead.
**Choice D is incorrect.** If bird measures sometimes harm arthropods, conservationists would not be satisfied that those measures protect all wildlife; this choice contradicts the passage’s conclusion.
**Faster approach:** Look for the answer that explains how one set of mitigations can cover multiple groups —choose the option that states the bird protections also reduce harms to arthropods.'),
  ('3c8ef8ff-a4e5-5562-82bb-2d912dc17715', 0, null, '**Choice A is correct.** The passage states that ranking considered cannons and decks and gives two examples: the Dreadnought had 98 cannons and three decks but was not first-rate, while the Caledonia had 120 cannons and three decks and was first-rate. Because both ships had three decks but only one was first-rate, we can conclude that having three decks alone does not guarantee a first-rate ranking; in other words, not all ships with three decks were ranked as first-rate.
**Choice B is incorrect.** The Dreadnought had 98 cannons but was not ranked first-rate, so having at least 98 cannons cannot be sufficient for first-rate status.
**Choice C is incorrect.** The passage says first-rate ships had between 850 and 875 crewmen; it does not state the Dreadnought’s crew size, and since the Dreadnought was not first-rate, we cannot infer it had that crew range.
**Choice D is incorrect.** The passage gives no information that first-rate ships needed more than 875 crewmen; it explicitly gives the first-rate range as 850–875, so there is no basis to conclude the Caledonia needed a crew larger than 875.
**Faster approach:** Compare the two example ships feature by feature (cannons, decks, rank). If one shared a feature with the other but had a different rank, you can immediately infer that feature alone is not sufficient for that rank. This elimination method works for any inference question using paired examples.'),
  ('5733de3f-4427-5906-941e-4d6e0c2db5df', 0, null, '**Choice A is correct.** The study’s finding — that strong democracy combined with low inequality restrains inflation — would lead a reader to expect a country like Austria to have relatively low inflation. Because Austria’s 2017 inflation rate exceeded Cameroon’s despite Austria’s stronger democratic institutions and lower inequality, the most logical inference is that factors other than political structure and inequality explain Austria’s higher inflation that year.
**Choice B is incorrect.** The sentence after "which would suggest that" needs to reconcile the apparent contradiction; it does not follow that inequality primarily explains the difference, since the study predicts low inflation for democracies with low inequality.
**Choice C is incorrect.** The passage treats the indices as given; the study’s general finding, not a reassessment of the indices, prompts the inference that other factors are at work.
**Choice D is incorrect.** This asserts a causal counterfactual about government control increasing inflation, which is not supported by the study’s conclusion emphasizing that democracy plus low inequality restrains inflation.
**Faster approach:** Compare the general claim to the specific example; if the example contradicts the general claim, conclude that additional factors must be responsible.'),
  ('0cf34666-d92c-54d9-8c8a-fd0f7a3f6cfe', 1, null, '**Choice B is correct.** The phrase names the subject (the three researchers) followed immediately by the verb "compiled." Standard English does not put punctuation between a subject and its verb, so no comma or other mark should separate the list of names from the verb that follows.
**Choice A is incorrect.** A comma after "Torres-Sánchez" would create an unnecessary break between the subject and verb; commas are used for nonessential clauses or to separate items, not to separate a subject from its verb.
**Choice C is incorrect.** A semicolon cannot correctly separate a subject from its verb; semicolons join independent clauses or complex list items, which is not the case here.
**Choice D is incorrect.** A colon is used to introduce a list or an explanation and cannot correctly appear between a subject and its verb.
**Faster approach:** Remember the basic rule: never place punctuation (comma, semicolon, colon) between a subject and its verb; if one of those marks appears there, choose the option with no punctuation.'),
  ('563fc76c-baf2-57fb-a903-4f423ca2105a', 0, null, '**Choice A is correct.** The sentence completes a simple independent clause stating a fact: "the average summer temperature is just 66.7 degrees Fahrenheit." No additional clause or list follows, so a plain verb without added punctuation is appropriate; the sentence reads smoothly and is grammatically complete with just "is."
**Choice B is incorrect.** A semicolon ("is;") separates independent clauses; here it would create a fragment after the semicolon and is grammatically incorrect.
**Choice C is incorrect.** A colon ("is:") introduces a list or explanation that follows; nothing follows, so the colon would be inappropriate and leave the sentence incomplete.
**Choice D is incorrect.** A comma ("is,") would create an unnecessary pause and usually signals a following clause or phrase; since none follows, the comma is wrong.
**Faster approach:** Read the sentence as a complete statement—if nothing follows that needs to be introduced or joined, choose the bare verb (no extra punctuation).'),
  ('6a959cb4-e879-5db6-810e-43db64e3dbfa', 1, null, '**Choice B is correct.** The sentence following the question is a declarative statement: "It first appears in the poem The Faerie Queene by English author Edmund Spenser." To conform to Standard English, the intervening clause must also be a declarative clause that smoothly connects the two sentences. "it was invented by an author." is a complete declarative sentence that correctly uses capitalization and punctuation when placed after the introductory adverb "Interestingly,".
**Choice A is incorrect.** "it was invented by an author?" turns the intervening clause into a question, which is inconsistent with the following declarative sentence and punctuation.
**Choice C is incorrect.** "was it invented by an author." is an inverted question word order used for direct questions; as written it also ends with a period but retains question word order, so it is ungrammatical in context.
**Choice D is incorrect.** "wasn’t it invented by an author." is a tag/question form and would make the sentence a question; that is inconsistent with the declarative that follows and is not standard here.
**Faster approach:** Recognize that the context moves from a question about origin to a factual statement, so choose a declarative clause (period) with normal subject–verb order: subject then verb ("it was...").'),
  ('624b413c-4906-5f8b-91c0-1ba1f230da56', 0, null, '**Choice A is correct.** The sentence describes a sequence of past events: Land invented a filter in 1929 and, a decade later, he performed the action of using that technology to invent the Polaroid Land camera. The simple past verb "used" correctly matches the past-tense time frame and yields a grammatical main clause: "A decade later, Land used his technology to invent..."
**Choice B is incorrect.** "to have used" is a perfect infinitive that does not fit here; it creates an awkward temporal relationship and is ungrammatical in this context.
**Choice C is incorrect.** "to use" is an infinitive that would require a different sentence structure (e.g., "in order to use") and does not match the straightforward past narrative.
**Choice D is incorrect.** "using" would need a participial phrase (e.g., "Using his technology, Land invented...") but as placed it results in a sentence fragment or a dangling modifier.
**Faster approach:** Match verb tense to the time cue—because the sentence refers to events a decade later (past), choose a simple past verb form.'),
  ('1742591d-44e8-5a8c-bcfe-d3867a960dda', 1, null, '**Choice B is correct.** The phrase "the strings inside the instrument are plucked not struck" is a single independent clause in which "instrument" is the object of the preposition "inside" and is immediately followed by the verb phrase "are plucked not struck." No punctuation should separate the noun and its verb, so the sentence requires no intervening mark after "instrument."
**Choice A is incorrect.** A colon after "instrument" ("instrument:") would wrongly signal a list or explanation to follow and would create an ungrammatical break before the verb "are."
**Choice C is incorrect.** An em dash ("instrument—") would create an abrupt break or parenthetical element; here the sentence should flow directly into the verb, so the dash is inappropriate.
**Choice D is incorrect.** A period after "instrument." would end the sentence and leave the phrase "are plucked not struck" as a sentence fragment.
**Faster approach:** When the word before a blank is immediately followed by the verb that completes the clause, choose no punctuation (plain word) so the subject/verb connection remains intact.'),
  ('a5e98b7a-2cdb-5710-a970-a01bf4f44dc0', 2, null, '**Choice C is correct.** The clause introduced by "how" is a direct question: the writer asks both "What are atmospheric rivers" and "how do they affect our weather?" In standard English a direct question requires subject–auxiliary inversion ("do they") and a question mark, so "do they affect our weather?" correctly completes the sentence.
**Choice A is incorrect.** It uses subject–auxiliary order for a statement ("do they affect our weather.") where a question is required and it ends with a period, which is ungrammatical here.
**Choice B is incorrect.** It gives a declarative clause ("they do affect our weather.") rather than a question; because the sentence pairs two questions, the second clause must also be a question.
**Choice D is incorrect.** Although it has a question mark, it uses declarative word order ("they do") rather than the required inverted order ("do they").
**Faster approach:** When a sentence pairs two questions joined by "and," use subject–auxiliary inversion and a question mark for the second clause—look for "do/does/did + subject" and a final question mark.'),
  ('265f317f-a8a6-5789-8b80-cbe3ebcb65cf', 3, null, '**Choice D is correct.** The sentence sets up a three-part explanation of the impact, so a colon properly introduces the list of effects: "threefold: expanding, challenging, and shedding light..." The colon signals that what follows explains or enumerates the threefold impact, and the participial phrases form a coordinated series describing those effects.
**Choice A is incorrect.** A semicolon separates two independent clauses; "expanding the horizons..." is not an independent clause and cannot follow a semicolon.
**Choice B is incorrect.** Omitting punctuation between "threefold" and "expanding" creates a run-on noun phrase that fails to mark that what follows is an explanation or list of the threefold impact.
**Choice C is incorrect.** A period creates two sentences, but "expanding the horizons..." begins with a lowercase participle and cannot stand alone as a complete sentence.
**Faster approach:** When a sentence announces a count or summary word (like "threefold"), use a colon to introduce the explanation or list that follows.'),
  ('c89cf1b2-8731-5fe2-a509-360daaaefda2', 2, null, '**Choice C is correct.** The sentence before the blank states that the statues "are made of stone and are extremely heavy," so the next sentence should reinforce that claim with a specific detail; "In fact, they each weigh more than 5 tons!" provides that supporting detail and is the most logical continuation.
**Choice A is incorrect.** "In any case," signals a dismissal or shift that does not supply the specific supporting information implied by the preceding sentence.
**Choice B is incorrect.** "Earlier," introduces a time sequence and would require reference to a prior event, which the context does not provide.
**Choice D is incorrect.** "Instead," indicates contrast or substitution, which conflicts with the preceding statement that the statues are heavy rather than elaborating on it.
**Faster approach:** Look for whether the second sentence should reinforce (use "In fact"), contrast ("Instead"), shift time ("Earlier"), or dismiss ("In any case"); match the transition to that relationship quickly.'),
  ('e52d9843-ba9b-5b69-80e9-c64b3a7881cb', 2, null, '**Choice C is correct.** The sentence gives two events with dates (2014 and 2017), so a temporal transition that indicates sequence is most logical. "Later," smoothly connects the earlier 2014 event to the 2017 action of creating the show and signals chronological progression.
**Choice A is incorrect.** "Instead," signals contrast or replacement, but the second clause is not opposing the first; it continues the subject’s activities, so contrast is inappropriate.
**Choice B is incorrect.** "For example," introduces an instance that illustrates a preceding general statement, but the first clause names a specific event, so an illustrative phrase doesn’t fit.
**Choice D is incorrect.** "In other words," restates or clarifies the prior idea; here the second clause presents a new, later action rather than a paraphrase.
**Faster approach:** Look for time markers (years, dates) and choose a temporal transition such as "later," "then," or "subsequently."'),
  ('81f13ead-385c-52cb-99f0-097d94ab4d3b', 3, null, '**Choice D is correct.** The sentence before the blank says that "Regardless of subject matter, Montaigne works to question his own perspective throughout his essays." The transition "Still," signals a contrast that concedes the previous point but introduces an additional idea—here, that he does this questioning even when topics seem light. That fits the logical flow: even so, he questions himself across essays.
**Choice A is incorrect.** "Fittingly," would suggest the next clause explains why the preceding statement is appropriate or expected, but the sentence needs a contrasting connective that emphasizes continuation despite subject differences, not a comment on suitability.
**Choice B is incorrect.** "Conversely," indicates a direct reversal of the previous idea; it would set up an opposing claim rather than the concession/continuation intended by the context.
**Choice C is incorrect.** "Nowadays," shifts the time frame to the present and would be appropriate only if the next clause discussed contemporary practices—irrelevant to the logical relation established here between topics and Montaigne’s consistent self-questioning.
**Faster approach:** For transition questions, identify whether the sentence needs to show
contrast/concession, cause, sequence, or time. Match that relation to the transition word: use "Still"/"However" for concession, "Because"/"Since" for cause, and temporal words like "Nowadays" only for time shifts. This decision alone usually pins the correct choice.'),
  ('84fe00cf-a693-5322-b870-5a4390d5c15b', 2, null, '**Choice C is correct.** The second sentence contrasts the idea of secrecy with what was more typical: supporters openly expressed antislavery views. The transition "More often," signals that the following clause states the usual situation (they were vocal abolitionists like LeMoyne), which fits the context that secrecy was uncommon.
**Choice A is incorrect.** "Fittingly," suggests that what follows is an appropriate or expected result, but the passage is emphasizing frequency (what was typical), not appropriateness.
**Choice B is incorrect.** "Granted," introduces a concession (acknowledging a point that might weaken the argument), which does not match the intended contrast about how common secrecy was.
**Choice D is incorrect.** "For example," would introduce an instance supporting a general claim, but the sentence needs to state the usual case rather than give an example.
**Faster approach:** Identify whether the context calls for contrast/frequency, concession, example, or result; then choose the transition that signals that logical relationship (here, frequency = "More often").'),
  ('5b556f41-e50c-547c-97a6-fae2bafdc3cd', 3, null, '**Choice D is correct.** The sentence explicitly gives the dates for both specimens—May 1930 for Achyrocline vauthieriana and February 1927 for Vernonia liatroides—and emphasizes their chronological relationship by saying one was collected after the other, which directly answers the prompt’s focus on when she collected both samples.
**Choice A is incorrect.** It highlights where the specimens can be viewed, not the dates when they were collected, so it doesn’t emphasize when the two samples were collected.
**Choice B is incorrect.** It mentions the date for only the Achyrocline specimen (May 3, 1930) and omits the date for the other sample, so it fails to emphasize when both were collected.
**Choice C is incorrect.** It contrasts locations and notes family membership but gives no dates, so it does not emphasize when the specimens were collected.
**Faster approach:** Scan choices for the one that names both collection dates (or states their order); that choice will best emphasize when both samples were collected.'),
  ('282175e2-b74d-5cf2-81f1-47efe215d1c4', 3, null, '**Choice D is correct.** It directly uses the note that Sirius A has a mass of 2.063 solar masses and relates that to the second note (one solar mass ≈ mass of the Sun) to emphasize Sirius A’s mass relative to the Sun, making the point clear and focused on Sirius A.
**Choice A is incorrect.** It mentions the unit (solar masses) and Proxima Centauri but does not mention Sirius A or emphasize its mass.
**Choice B is incorrect.** It accurately explains the unit solar mass but provides no information about Sirius A specifically, so it fails to emphasize Sirius A’s mass.
**Choice C is incorrect.** It compares the Sun and Proxima Centauri and gives Proxima’s mass but says nothing about Sirius A, so it does not accomplish the student’s goal.
**Faster approach:** Look for the answer that names Sirius A and states its mass or comparison; eliminate choices that omit Sirius A or only define units.'),
  ('71fd4fe4-29fb-5a6c-89c5-d64477bd208f', 3, null, '**Choice D is correct.** It directly states the shared characteristic from the notes: both programs are documentary slow TV that document ordinary events in real time. This matches the first note and applies it to both All Aboard! The Sleigh Ride and Monsen: Minutt for Minutt, emphasizing their similarity.
**Choice A is incorrect.** Although accurate about one program, it highlights a single example rather than emphasizing a similarity between the two programs.
**Choice B is incorrect.** It contrasts the two programs by describing different events each depicts, which emphasizes differences rather than a shared trait.
**Choice C is incorrect.** It compares running times and emphasizes a contrast in length instead of the common genre and documentary approach the student wants to highlight.
**Faster approach:** Scan the notes for words repeated or stated generally (here "slow TV" and "documentary"); choose the answer that applies that general descriptor to both items to show similarity.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
